import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/shared/lib/utils'
import { Slot } from 'radix-ui'

// Generated by shadcn (radix-vega), restyled to the canvas `.btn` rules in design/sino-ui/project/sino.css.
const buttonVariants = cva(
  "inline-flex shrink-0 cursor-pointer items-center justify-center gap-2 rounded-full border border-transparent text-sm font-extrabold tracking-[-0.005em] whitespace-nowrap select-none transition-[background-color,border-color,color,transform] duration-(--dur-hover) ease-out outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring focus-visible:outline-solid disabled:pointer-events-none disabled:opacity-38 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4.5",
  {
    variants: {
      variant: {
        primary: 'bg-primary text-primary-foreground shadow-[0_8px_18px_-10px_var(--accent)] hover:bg-primary-hover',
        soft: 'bg-brand-soft text-brand-ink hover:bg-brand-tint/40',
        secondary: 'bg-surface font-bold text-foreground shadow-[inset_0_0_0_1.5px_var(--border)] hover:bg-hover',
        ghost: 'font-bold text-muted-foreground hover:bg-hover hover:text-foreground',
        danger: 'bg-surface font-bold text-danger-ink shadow-[inset_0_0_0_1.5px_var(--danger)] hover:bg-danger-soft',
      },
      size: {
        default: 'h-11 px-4.5',
        sm: "h-9 px-3.5 text-[13px] [&_svg:not([class*='size-'])]:size-4",
        icon: 'size-11',
        'icon-sm': "size-9 [&_svg:not([class*='size-'])]:size-4",
      },
    },
    defaultVariants: {
      variant: 'primary',
      size: 'default',
    },
  },
)

function Button({
  className,
  variant = 'primary',
  size = 'default',
  asChild = false,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const Comp = asChild ? Slot.Root : 'button'

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button }
